"""Arrivals as a non-homogeneous Poisson process, generated by thinning.

The Lewis–Shedler algorithm draws candidates from a homogeneous Poisson
process with a constant rate ``bound >= lambda(t)`` and keeps each candidate
with probability ``lambda(t) / bound``. The kept candidates are exactly a
Poisson process with rate ``lambda(t)``: no integration and no inversion of
``Lambda`` are needed.

The bound is set per day, as ``day_scale(day) * max(h)``. With the linear
interpolation of the hourly shape, lambda never exceeds the largest hour
factor, so the bound is tight and about 60 % of the candidates are kept.
The bound is checked at every candidate: a bound below lambda would cut the
peaks without any warning, so it raises instead.

The generator is lazy: it draws the next candidate only when the next arrival
is asked for, so it can run live, one arrival at a time, inside SimPy.

Randomness (ADR 0007): ``SeedSequence(seed).spawn(2)`` gives two streams. The
first one draws the candidates (the gap and then, if the candidate falls
inside the day, the acceptance uniform). The second one is reserved for the
daily random effect Z of task 2.3, so that turning the overdispersion on or
off does not change the sequence of candidates.
"""

import math
from collections.abc import Callable, Generator, Iterable, Iterator
from dataclasses import dataclass
from datetime import date, timedelta

import numpy as np
import simpy

from edsim.arrivals.profile import ArrivalProfile
from edsim.arrivals.rate import MINUTES_PER_DAY, cumulative_rate, day_scale, shape

_ROUNDING = 1e-12
"""Relative margin for lambda over the bound, which may differ in the last bits."""


@dataclass(frozen=True, slots=True)
class ArrivalRecord:
    """One arrival.

    Attributes:
        arrival_id: Arrival order, starting at 0.
        time: Minutes since 00:00 of the profile's ``start_date``. The date
            and the time of day are derived from it and not stored.
    """

    arrival_id: int
    time: float


@dataclass(frozen=True, slots=True)
class DayRecord:
    """Ground truth of one simulated day (ADR 0006).

    Attributes:
        day: Day index, 0 for the profile's ``start_date``.
        date: Calendar date of the day.
        day_effect: Daily random effect Z. Always 1 until task 2.3.
        expected: Expected arrivals of the day: Lambda at its end minus
            Lambda at its start.
        bound: Thinning bound of the day, in arrivals per minute.
        candidates: Candidates drawn inside the day. The candidate that falls
            past midnight is discarded and not counted.
        accepted: Candidates kept, which are the arrivals of the day.
    """

    day: int
    date: date
    day_effect: float
    expected: float
    bound: float
    candidates: int
    accepted: int


def _check_days(days: object) -> int:
    # bool is a subclass of int in Python: True must not pass as 1 day.
    if isinstance(days, bool) or not isinstance(days, int) or days < 1:
        raise ValueError(f"days must be a positive integer, got {days!r}")
    return days


def _check_bound_factor(bound_factor: object) -> float:
    if (
        isinstance(bound_factor, bool)
        or not isinstance(bound_factor, int | float)
        or not math.isfinite(bound_factor)
        or bound_factor <= 0
    ):
        raise ValueError(f"bound_factor must be a finite positive number, got {bound_factor!r}")
    return float(bound_factor)


def iter_arrivals(
    profile: ArrivalProfile,
    days: int,
    seed: int | np.random.SeedSequence,
    *,
    on_day: Callable[[DayRecord], None] | None = None,
    bound_factor: float = 1.0,
) -> Iterator[ArrivalRecord]:
    """Generate the arrivals of ``days`` full days, lazily and in order.

    For each day, the generator starts at 00:00 with the bound of the day and
    draws candidates with exponential gaps of mean ``1 / bound``. A candidate
    at ``t`` is kept if ``U * bound <= lambda(t)``, with ``U`` uniform. When a
    candidate falls past midnight it is discarded and the next day starts
    again at its 00:00 with its own bound; the exponential has no memory, so
    restarting is exact.

    The daily random effect is not applied yet: ``day_effect`` is 1 and the
    profile's ``daily_cv`` is ignored until task 2.3.

    Arguments are checked on the call, before the first arrival is asked for.

    Args:
        profile: The arrival profile.
        days: Number of full days to simulate, from the profile's
            ``start_date``; a positive integer.
        seed: Seed of the run: an integer or a ``numpy.random.SeedSequence``,
            such as one child of ``SeedSequence(master).spawn(R)`` per
            replication. An integer is equivalent to ``SeedSequence(seed)``.
        on_day: Called with the ``DayRecord`` of each day when the day is
            closed: after its last arrival, when the next one is asked for (or
            when the generator is exhausted). A day left unfinished, because
            the consumer stopped asking, is not reported.
        bound_factor: Multiplies the bound of every day. Only for tests and
            teaching: a value below 1 makes the bound too low and the
            generator raises.

    Returns:
        An iterator of ``ArrivalRecord``, with consecutive ``arrival_id``.

    Raises:
        ValueError: If ``days`` is not a positive integer or ``bound_factor``
            is not a finite positive number.
        RuntimeError: While iterating, if lambda exceeds the bound of the day
            at a candidate.
    """
    days = _check_days(days)
    bound_factor = _check_bound_factor(bound_factor)
    seed_seq = seed if isinstance(seed, np.random.SeedSequence) else np.random.SeedSequence(seed)
    # Second child: daily effect Z, task 2.3.
    arrivals_seq, _day_effect_seq = seed_seq.spawn(2)
    rng = np.random.default_rng(arrivals_seq)
    return _thinning(profile, days, rng, on_day, bound_factor)


def _thinning(
    profile: ArrivalProfile,
    days: int,
    rng: np.random.Generator,
    on_day: Callable[[DayRecord], None] | None,
    bound_factor: float,
) -> Iterator[ArrivalRecord]:
    max_h = max(profile.hour_factors)
    next_id = 0

    for day in range(days):
        start = day * MINUTES_PER_DAY
        end = start + MINUTES_PER_DAY
        # lambda(t) = scale * shape(minute): the scale is computed once per day.
        scale = day_scale(day, profile)
        bound = scale * max_h * bound_factor
        candidates = accepted = 0

        t = float(start)
        while True:
            # numpy's exponential takes the scale (mean = 1 / rate), not the rate.
            t += rng.exponential(1 / bound)
            if t >= end:
                break  # past midnight: discarded, the next day restarts at 00:00
            candidates += 1
            lam = scale * shape(t - start, profile)
            if lam > bound * (1 + _ROUNDING):
                raise RuntimeError(
                    f"thinning bound too low on day {day}: lambda({t:.4f}) = {lam:.6g} "
                    f"exceeds the bound {bound:.6g}"
                )
            if rng.random() * bound <= lam:
                accepted += 1
                yield ArrivalRecord(arrival_id=next_id, time=t)
                next_id += 1

        if on_day is not None:
            expected = cumulative_rate(end, profile) - cumulative_rate(start, profile)
            on_day(
                DayRecord(
                    day=day,
                    date=profile.start_date + timedelta(days=day),
                    day_effect=1.0,
                    expected=expected,
                    bound=bound,
                    candidates=candidates,
                    accepted=accepted,
                )
            )


def simulate_arrivals(
    profile: ArrivalProfile, days: int, seed: int | np.random.SeedSequence
) -> tuple[tuple[ArrivalRecord, ...], tuple[DayRecord, ...]]:
    """Generate all the arrivals of ``days`` full days, for batch analysis.

    Consumes ``iter_arrivals`` entirely; see it for the algorithm and the
    arguments.

    Returns:
        The arrivals in order and one ``DayRecord`` per day.

    Raises:
        ValueError: If ``days`` is not a positive integer.
    """
    day_records: list[DayRecord] = []
    arrivals = tuple(iter_arrivals(profile, days, seed, on_day=day_records.append))
    return arrivals, tuple(day_records)


def arrival_source(
    env: simpy.Environment,
    arrivals: Iterable[ArrivalRecord],
    on_arrival: Callable[[ArrivalRecord], None],
) -> Generator[simpy.Event]:
    """SimPy process that waits until each arrival and passes it on.

    ``on_arrival`` gets the original record, whose ``time`` is the generated
    one: ``env.now`` adds up the waits and may differ from it in the last
    digit.

    Args:
        env: The SimPy environment.
        arrivals: Arrival records in time order, such as the tuple from
            ``simulate_arrivals`` or the lazy ``iter_arrivals`` itself.
        on_arrival: Called at the time of each arrival with its record.
    """
    for arrival in arrivals:
        # Never negative: env.now may be one bit past the record's time.
        yield env.timeout(max(0.0, arrival.time - env.now))
        on_arrival(arrival)
